bookInfoRule.init:
@js:
var Regs = [/book_id=(\d+)/i, /d=(\d+)/i, /(\d+)/i];
var book_id = "";
for (let Reg of Regs) {
    let mat = baseUrl.match(Reg);
    if (mat) {
        book_id = mat[1];
        break;
    }
}

if (!book_id) throw new Error("没有 book_id !")
java.put("book_id", book_id)

var u_Index = 0; // 0-1
switch (String(['API', 'TOU'][u_Index])) {
    case 'API':
        result = java.ajax(xGorgon(
            "detail",
            "book_id=" + book_id
        ));
        if (JSON.parse(result).code == 0) break;
        // java.log("接口异常，使用头条接口获取");

        // 这两个接口信息不全
        // result = java.ajax("https://fanqienovel.com/page/"+book_id).match(/__INITIAL_STATE__=([^;]+)/)[1];
        // result = java.ajax(getHost(1,3,1,5)+"/reading/bookapi/multi-detail/v/?aid=1967&iid=1&version_code=999&book_id="+book_id);

        // 头条接口
    default:
        result = java.ajax("https://novel.snssdk.com/api/novel/book/directory/list/v1/?device_platform=android&version_code=1207&novel_version=&app_name=gold_browser&version_name=2.0.7&channel=vivo_6589_64&device_type=wldw&os_api=28&os_version=9&book_id=" + book_id);
        break;
}

try {
  xGorgon(
    "/reading/bookapi/read_history/update/v/?", "",
    gzip(JSON.stringify({
      update_datas: [{
        book_id: book_id,
        read_timestamp_ms: Date.now()
      }]
    }).replace(/\"(\d+)\"/g, "$1")), java.getCookie("fanqienovel.com")
)} catch (e) {
  java.toast("无法更新阅读历史: " + e)
  java.log("无法更新阅读历史: " + e.stack)
}

var Res  = JSON.parse(result);
var data = Res.page || Res.data;
data = (Array.isArray(data) ? data[0] : data.book_info) || data;
JSON.stringify(data);

